import type { ComponentProps } from "react";

import { getNetworkLabel, type BitcoinNetwork } from "@/lib/bitcoin";
import { componentClasses } from "@/lib/utils";

import { badgeStyles, type BitcoinVisualProps } from "./shared";

const networkStyles: Record<BitcoinNetwork, string> = {
  mainnet:
    "border-[var(--color-bitcoin)]/30 bg-[var(--color-bitcoin-soft)] text-[var(--color-bitcoin-ink)]",
  testnet:
    "border-[var(--color-info)]/30 bg-[var(--color-info-soft)] text-[var(--color-info)]",
  signet:
    "border-[var(--color-warning)]/30 bg-[var(--color-warning-soft)] text-[var(--color-warning)]",
  regtest:
    "border-[var(--color-rule)] bg-[var(--color-surface)] text-[var(--color-muted-strong)]",
};

export type NetworkBadgeProps = Omit<ComponentProps<"span">, "children"> &
  BitcoinVisualProps & {
    network: BitcoinNetwork;
    /** Shows the small network indicator dot. @default true */
    showIndicator?: boolean;
  };

export function NetworkBadge({
  network,
  showIndicator = true,
  unstyled,
  className,
  ...props
}: NetworkBadgeProps) {
  return (
    <span
      data-slot="network-badge"
      data-network={network}
      data-unstyled={unstyled || undefined}
      className={componentClasses(
        unstyled,
        [badgeStyles, networkStyles[network]],
        className,
      )}
      {...props}
    >
      {showIndicator ? (
        <span
          data-slot="network-badge-indicator"
          aria-hidden="true"
          className={componentClasses(
            unstyled,
            "size-1.5 rounded-full bg-current",
          )}
        />
      ) : null}
      {getNetworkLabel(network)}
    </span>
  );
}

import {
  CircleAlert,
  CircleCheck,
  Clock3,
  Replace,
  type LucideIcon,
} from "lucide-react";
import type { ComponentProps } from "react";

import type { TransactionState } from "@/lib/bitcoin";
import { componentClasses } from "@/lib/utils";

import { badgeStyles, type BitcoinVisualProps } from "./shared";

const statusConfig: Record<
  TransactionState,
  { label: string; icon: LucideIcon; styles: string }
> = {
  confirmed: {
    label: "Confirmed",
    icon: CircleCheck,
    styles:
      "border-[var(--color-success)]/30 bg-[var(--color-success-soft)] text-[var(--color-success)]",
  },
  pending: {
    label: "In mempool",
    icon: Clock3,
    styles:
      "border-[var(--color-warning)]/30 bg-[var(--color-warning-soft)] text-[var(--color-warning)]",
  },
  replaced: {
    label: "Replaced",
    icon: Replace,
    styles:
      "border-[var(--color-info)]/30 bg-[var(--color-info-soft)] text-[var(--color-info)]",
  },
  conflicted: {
    label: "Conflicted",
    icon: CircleAlert,
    styles:
      "border-[var(--color-danger)]/30 bg-[var(--color-danger-soft)] text-[var(--color-danger)]",
  },
};

export type StatusBadgeProps = Omit<ComponentProps<"span">, "children"> &
  BitcoinVisualProps & {
    state: TransactionState;
    label?: string;
    showIcon?: boolean;
  };

export function StatusBadge({
  state,
  label,
  showIcon = true,
  unstyled,
  className,
  ...props
}: StatusBadgeProps) {
  const config = statusConfig[state];
  const Icon = config.icon;

  return (
    <span
      data-slot="status-badge"
      data-state={state}
      data-unstyled={unstyled || undefined}
      className={componentClasses(
        unstyled,
        [badgeStyles, config.styles],
        className,
      )}
      {...props}
    >
      {showIcon ? (
        <Icon
          data-slot="status-badge-icon"
          className={componentClasses(unstyled, "size-3")}
          aria-hidden="true"
        />
      ) : null}
      {label ?? config.label}
    </span>
  );
}

import type { ComponentProps } from "react";

import { getScriptLabel, type ScriptType } from "@/lib/bitcoin";
import { componentClasses } from "@/lib/utils";

import { badgeStyles, type BitcoinVisualProps } from "./shared";

export type ScriptBadgeProps = Omit<ComponentProps<"span">, "children"> &
  BitcoinVisualProps & {
    type: ScriptType;
  };

export function ScriptBadge({
  type,
  unstyled,
  className,
  ...props
}: ScriptBadgeProps) {
  return (
    <span
      data-slot="script-badge"
      data-script-type={type}
      data-unstyled={unstyled || undefined}
      className={componentClasses(
        unstyled,
        [
          badgeStyles,
          "rounded-[var(--radius-xs)] bg-[var(--color-surface)] font-mono text-[0.6875rem] font-medium text-[var(--color-muted-strong)]",
          type === "p2tr" &&
            "border-[var(--color-bitcoin)]/30 bg-[var(--color-bitcoin-soft)] text-[var(--color-bitcoin-ink)]",
          type === "op-return" &&
            "border-[var(--color-danger)]/30 bg-[var(--color-danger-soft)] text-[var(--color-danger)]",
        ],
        className,
      )}
      {...props}
    >
      {getScriptLabel(type)}
    </span>
  );
}
